"""RoboPaint stroke-copy controller. Uses only documented RGB/depth and robot APIs."""
import sys,os,json,time,math
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); RUN=Path('/app/runs')
class Painter:
 def __init__(self):
  self.r=Robot();self.spec=self.r.spec();self.rows=[]
  self.seq=len(list(RUN.glob('call_*')))
  o=self.r.get_obs(cameras=[]);self.p=np.array(o.meta['proprio']['now'][7:14]);self.q=np.array([0.,1.,0.,0.]);self.p[3:]=self.q
 def send(self,rows,note=''):
  rows=np.asarray(rows)
  for i in range(0,len(rows),180):
   chunk=rows[i:i+180];before=self.r.status();self.seq+=1
   d=RUN/f'call_{self.seq:04d}';d.mkdir(exist_ok=True);np.save(d/'actions.npy',chunk)
   (d/'request.json').write_text(json.dumps({'type':'ee_pose','dt':.05,'note':note,'before':before}))
   try:res=self.r.submit('ee_pose',chunk,dt=.05,cameras=[],video='none',note=note)
   except Exception:
    after=self.r.wait_ready();(d/'recovery.json').write_text(json.dumps(after))
    if after['calls']==before['calls']:res=self.r.submit('ee_pose',chunk,dt=.05,cameras=[],video='none',note=note)
    else:continue
   (d/'meta.json').write_text(json.dumps(res.meta))
   if res.meta.get('plan'):print('PLAN',res.meta['plan'],flush=True)
   if res.stopped:raise RuntimeError('Partial call, inspect before continuing')
   if res.done:raise RuntimeError('Episode finished')
  self.p=rows[-1].copy()
 def path(self,points,speed=.08,hold=0):
  rows=[];prev=self.p.copy()
  for xyz in points:
   nxt=np.r_[xyz,self.q];n=max(1,math.ceil(np.linalg.norm(nxt[:3]-prev[:3])/(speed*.05)))
   rows.extend(np.linspace(prev,nxt,n+1)[1:]);prev=nxt
  rows.extend([prev.copy()]*round(hold/.05));self.send(rows)
 def move(self,xyz,speed=.1,hold=.2):self.path([xyz],speed,hold)
 def dip(self,c):
  x=-.156+(c%5)*.028;y=.146+(c//5)*.028
  self.move([self.p[0],self.p[1],.075]);self.move([x,y,.075]);self.move([x,y,.025],.04,.4);self.move([x,y,.075],.04,.2)
 def stroke_world(self,points,speed=.02):
  points=np.array(points);self.move([points[0,0],points[0,1],.04],.12,.15)
  self.move(points[0],.025,.15);self.path(points[1:],speed,.15);self.move([points[-1,0],points[-1,1],.04],.04,.15)
 def park(self):self.move([-.24,0,.12],.1,.4)
 def observe(self,name,cameras=['canvas_cam','practice_cam','scene_cam']):
  o=self.r.get_obs(cameras=cameras,depth=True);o.save(RUN/name)
  for cam,im in o.last.items():Image.fromarray(im).save(RUN/name/(cam+'.png'))
  print('STATUS',self.r.status(),flush=True);return o
if __name__=='__main__':
 p=Painter()
 if sys.argv[1]=='practice':
  p.dip(5)
  for i,dep in enumerate([.0005,.001,.002,.004,.007,.010]):
   x=-.01-i*.03
   p.stroke_world([[x,-.151,.020-dep],[x,-.212,.020-dep]],.02)
  p.park();p.observe('practice1')
PY
